SELECT * FROM knowledge_graph_node
WHERE node_name = #{nodeName} AND node_type = #{nodeType}

    AND student_id = #{studentId}

LIMIT 1

SELECT DISTINCT n.*
FROM knowledge_graph_node n
LEFT JOIN knowledge_graph_edge e1 ON n.id = e1.source_node_id
LEFT JOIN knowledge_graph_edge e2 ON n.id = e2.target_node_id
WHERE (e1.source_node_id IN (
    SELECT id FROM knowledge_graph_node WHERE node_name = #{centerNodeName}

        AND student_id = #{studentId}

)
OR e2.target_node_id IN (
    SELECT id FROM knowledge_graph_node WHERE node_name = #{centerNodeName}

        AND student_id = #{studentId}

)
OR n.node_name = #{centerNodeName})

    AND n.student_id = #{studentId}

SELECT * FROM knowledge_graph_node
WHERE student_id = #{studentId}
ORDER BY level ASC, create_time DESC

SELECT * FROM knowledge_graph_node
WHERE node_type = #{nodeType}

    AND student_id = #{studentId}

ORDER BY level ASC, create_time DESC

